            return FfiConverterOptionalByteArray.lift(
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_bwphone_android_fn_method_framedecoder_next_frame(
        it, _status)
}
    }
