    }
    

    

    
    
    companion object
    
}

/**
 * @suppress
 */
public object FfiConverterTypeTransport: FfiConverter<Transport, Pointer> {

    override fun lower(value: Transport): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): Transport {
        return Transport(value)
    }

    override fun read(buf: ByteBuffer): Transport {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: Transport) = 8UL

    override fun write(value: Transport, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



