/**
 * What the PC asks. Binary fields arrive decoded and length-checked.
 */
sealed class PhoneRequest {
    
    /**
     * Answer `Pong`; show nothing.
     */
    object Ping : PhoneRequest()
    
    
    /**
     * Compare `H(rsa_ct)` to the account's pin first; refuse a mismatch
     * without a prompt. Then reply `PromptPosted` with a fresh `phone_nonce()`,
     * derive the emoji with `emoji_index`, emoji pick, then `BiometricPrompt`.
     * `host` is caller-supplied text: log it if you like, never show it.
     */
    data class Unwrap(
        val `account`: kotlin.ByteArray, 
        val `rsaCt`: kotlin.ByteArray, 
        val `expiresInMs`: kotlin.ULong, 
        val `nonce`: kotlin.ByteArray, 
        val `host`: kotlin.String) : PhoneRequest() {
        companion object
    }
    
    /**
     * Refuse unless the Enrol screen is open.
     */
    data class EnrolBegin(
        val `account`: kotlin.ByteArray, 
        val `labelHint`: kotlin.String) : PhoneRequest() {
        companion object
    }
    
    /**
     * Write-once, Enrol screen only.
     */
    data class SetPin(
        val `account`: kotlin.ByteArray, 
        val `pin`: kotlin.ByteArray) : PhoneRequest() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypePhoneRequest : FfiConverterRustBuffer<PhoneRequest>{
    override fun read(buf: ByteBuffer): PhoneRequest {
        return when(buf.getInt()) {
            1 -> PhoneRequest.Ping
            2 -> PhoneRequest.Unwrap(
                FfiConverterByteArray.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> PhoneRequest.EnrolBegin(
                FfiConverterByteArray.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> PhoneRequest.SetPin(
                FfiConverterByteArray.read(buf),
                FfiConverterByteArray.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PhoneRequest) = when(value) {
        is PhoneRequest.Ping -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is PhoneRequest.Unwrap -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`account`)
                + FfiConverterByteArray.allocationSize(value.`rsaCt`)
                + FfiConverterULong.allocationSize(value.`expiresInMs`)
                + FfiConverterByteArray.allocationSize(value.`nonce`)
                + FfiConverterString.allocationSize(value.`host`)
            )
        }
        is PhoneRequest.EnrolBegin -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`account`)
                + FfiConverterString.allocationSize(value.`labelHint`)
            )
        }
        is PhoneRequest.SetPin -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`account`)
                + FfiConverterByteArray.allocationSize(value.`pin`)
            )
        }
    }

    override fun write(value: PhoneRequest, buf: ByteBuffer) {
        when(value) {
            is PhoneRequest.Ping -> {
                buf.putInt(1)
                Unit
            }
            is PhoneRequest.Unwrap -> {
                buf.putInt(2)
                FfiConverterByteArray.write(value.`account`, buf)
                FfiConverterByteArray.write(value.`rsaCt`, buf)
                FfiConverterULong.write(value.`expiresInMs`, buf)
                FfiConverterByteArray.write(value.`nonce`, buf)
                FfiConverterString.write(value.`host`, buf)
                Unit
            }
            is PhoneRequest.EnrolBegin -> {
                buf.putInt(3)
                FfiConverterByteArray.write(value.`account`, buf)
                FfiConverterString.write(value.`labelHint`, buf)
                Unit
            }
            is PhoneRequest.SetPin -> {
                buf.putInt(4)
                FfiConverterByteArray.write(value.`account`, buf)
                FfiConverterByteArray.write(value.`pin`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






enum class PhoneStatus {
    
    /**
     * Interim: the prompt is on screen. Ends the PC's reach phase.
     */
    PROMPT_POSTED,
    OK,
    PONG,
    DENIED,
    /**
     * None of these: the PC raises an alarm.
     */
    REJECTED,
    PIN_MISMATCH,
    RATE_LIMITED,
    BUSY,
    EXPIRED,
    INVALIDATED,
    UNKNOWN_ACCOUNT,
    NOT_ALLOWED,
    /**
     * enrol_begin for a name this phone already has.
     */
    LABEL_TAKEN,
    ERROR;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypePhoneStatus: FfiConverterRustBuffer<PhoneStatus> {
    override fun read(buf: ByteBuffer) = try {
        PhoneStatus.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: PhoneStatus) = 4UL

    override fun write(value: PhoneStatus, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







sealed class TransportException(message: String): kotlin.Exception(message) {
        
    /**
     * A handshake or transport message did not authenticate: the wrong
     * key, the wrong pairing ID, a replay, or garbage.
     */
        class Noise(message: String) : TransportException(message)
        
        class Malformed(message: String) : TransportException(message)
        
    /**
     * Used out of order, e.g. `into_transport` before the handshake ended.
     */
        class State(message: String) : TransportException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<TransportException> {
        override fun lift(error_buf: RustBuffer.ByValue): TransportException = FfiConverterTypeTransportError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeTransportError : FfiConverterRustBuffer<TransportException> {
    override fun read(buf: ByteBuffer): TransportException {
        
            return when(buf.getInt()) {
            1 -> TransportException.Noise(FfiConverterString.read(buf))
            2 -> TransportException.Malformed(FfiConverterString.read(buf))
            3 -> TransportException.State(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: TransportException): ULong {
        return 4UL
    }

    override fun write(value: TransportException, buf: ByteBuffer) {
        when(value) {
            is TransportException.Noise -> {
                buf.putInt(1)
                Unit
            }
            is TransportException.Malformed -> {
                buf.putInt(2)
                Unit
            }
            is TransportException.State -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




